h_gross_contribution_day_level_Beardo as SELECT order_timestamp::Date AS date, payment_method, weight_slab, expected_zone, expected_warehouse, COUNT(DISTINCT ordeR_id) AS orders, SUM(IFNULL(mrp_sales, 0)) AS mrp_sales, SUM(IFNULL(total_sales, 0)) AS total_sales, SUM(IFNULL(total_discount, 0)) AS total_discount, SUM(IFNULL(NR, 0)) AS NR, SUM(IFNULL(NR, 0) * (1 - y.return_rate)) AS expected_NR, SUM(IFNULL(total_cogs, 0)) AS total_cogs, SUM(IFNULL(total_cogs, 0) * (1 - y.return_rate)) AS expected_total_cogs, SUM(IFNULL(gokwik_charge, 0)) AS gokwik_charge, SUM(IFNULL(spm_cost, 0)) AS spm_cost, SUM(IFNULL(warehousing_cost, 0)) AS warehousing_cost, SUM(IFNULL(warehousing_cost, 0) + 6 * ifnull(WH_units_for_order,0) * IFNULL(y.return_rate, 0)) AS expected_warehousing_cost, SUM(IFNULL(logistics_cost, 0)) AS logistics_cost, SUM(CASE WHEN lower(payment_method) = \'prepaid\' THEN IFNULL(logistics_cost, 0) * (1 + IFNULL(y.return_rate, 0)) else (IFNULL(logistics_cost, 0) - 30) * (1 + IFNULL(y.return_rate, 0)) END) AS expected_logistics_cost, SUM(IFNULL(common_expense_finance, 0)) AS common_expense_finance, DIV0(300000 / DAY(LAST_DAY(order_timestamp::Date)), COUNT(*) OVER (PARTITION BY order_timestamp::Date ORDER BY 1)) AS daily_rent, SUM(IFNULL(NR, 0) * (1 - IFNULL(y.return_rate, 0))) - SUM(IFNULL(total_cogs, 0) * (1 - IFNULL(y.return_rate, 0))) - SUM(IFNULL(gokwik_charge, 0)) - SUM(IFNULL(warehousing_cost, 0) + 6 * IFNULL(y.return_rate, 0)) - SUM(IFNULL(common_expense_finance, 0)) - SUM(IFNULL(spm_cost, 0)) - SUM(CASE WHEN lower(payment_method) = \'prepaid\' THEN IFNULL(logistics_cost, 0) * (1 + IFNULL(y.return_rate, 0)) else (IFNULL(logistics_cost, 0) - 30) * (1 + IFNULL(y.return_rate, 0)) END) - ifnull(daily_rent,0) AS expected_GC, AVG(IFNULL(y.return_rate, 0)) AS return_rate FROM prd_db.beardo.dwh_gross_contribution_Beardo x LEFT JOIN ( SELECT a.date, b.return_rate FROM ( SELECT DISTINCT order_Date::Date AS date FROM prd_db.beardo.dwh_sales_consolidated ) a LEFT JOIN ( SELECT